INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('6905180a-504a-4feb-adc5-2320ec92ffad', 'CART_REMINDER', 'EMAIL', 0, 'You left something in your cart', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>Your cart is waiting</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">Your cart is waiting</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, you left these items in your cart at {{ shop.name }}. Finish your order in a minute and pay on delivery.</p>⏎</td></tr>⏎{% if cart.url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ cart.url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">Finish your order</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎{% for item in cart.line_items %}<tr>⏎<td width="56" style="padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;">{% if item.image_url %}<img src="{{ item.image_url }}" alt="" width="48" height="48" style="display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;">{% endif %}</td>⏎<td style="padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;">{{ item.title }}{% if item.variant_title %}<br><span style="color:#6b7280;font-size:13px;">{{ item.variant_title }}</span>{% endif %}<br><span style="color:#6b7280;font-size:13px;">Qty {{ item.quantity }}</span></td>⏎<td align="right" style="padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;">{{ item.line_price | money }}</td>⏎</tr>{% endfor %}⏎</table>⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:8px;">⏎<tr><td style="padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;">Total</td><td align="right" style="padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;">{{ cart.total | money }}</td></tr>⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-25T02:55:52.716Z', '2026-10-25T02:55:52.716Z', 'Abandoned cart reminder', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('257019ce-74fd-4a1e-bc59-56fef3ec343d', 'REVIEW_REQUEST', 'SMS', 0, NULL, 'How was your order {{order_number}}? Please leave a quick review: {{review_url}} - {{store_name}}', '2026-10-25T02:55:52.716Z', '2026-10-25T02:55:52.716Z', 'Review request', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('ecab57d5-4818-4ac3-b330-108400ccad85', 'REVIEW_REQUEST', 'WHATSAPP', 0, NULL, replace('Hi {{customer_first_name}}, how do you like your order {{order_number}}? A quick review would help us a lot: {{review_url}} Thank you!⏎⏎The {{store_name}} team', '⏎', char(10)), '2026-10-25T02:55:52.716Z', '2026-10-25T02:55:52.716Z', 'Review request', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
INSERT INTO "notifications" ("id", "event", "channel", "is_enabled", "subject", "template", "created_at", "updated_at", "name", "conditions", "merchant_id", "wa_name", "wa_language", "wa_status", "wa_reason", "wa_template_id", "wa_params", "wa_body", "wa_version", "wa_checked_at", "reply_buttons", "wa_buttons") VALUES ('0240d523-cd72-421a-b929-c7047f08abae', 'REVIEW_REQUEST', 'EMAIL', 0, 'How was your order {{ order.name }}?', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>How did we do?</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}Order {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">How did we do?</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, we hope you love your order {{ order.name }}. A one-minute review helps other shoppers, and it helps us a lot.</p>⏎</td></tr>⏎{% if shop.review_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ shop.review_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">Write a review</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Order</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Items</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Total</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">To pay on delivery</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-25T02:55:52.716Z', '2026-10-25T02:55:52.716Z', 'Review request', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
