INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('store_domains', '{"main_site":"store","root_domain":null}', 'Store addresses: root domain for store subdomains (needs wildcard DNS) and what the platform address shows (marketing or the default store)', NULL, '2026-10-25T02:55:52.128Z', '2026-10-25T02:55:52.128Z');
